import React from 'react';
import * as dd from '../knotfree-ts-lib/3d/messageTypes';


// Draw small boxes in the 4 lower corners of a cube, to make it easier to see the outline of the cube.
export function OutlineBoxComponent(props: { cube: dd.Cube }) {
    const { cube } = props
    const size = 0.1 * (2 ** cube.p)
    console.log(`OutlineBoxComponent cube`, cube, `size`, size)
    const halfSize = size / 2
    const corners: [number, number, number][] = [
        [cube.x - halfSize, cube.y - halfSize, cube.z - halfSize],
        [cube.x + halfSize, cube.y - halfSize, cube.z - halfSize],
        [cube.x - halfSize, cube.y + halfSize, cube.z - halfSize],
        [cube.x + halfSize, cube.y + halfSize, cube.z - halfSize],
        [cube.x - halfSize, cube.y - halfSize, cube.z + halfSize],
        [cube.x + halfSize, cube.y - halfSize, cube.z + halfSize],
        [cube.x - halfSize, cube.y + halfSize, cube.z + halfSize],
        [cube.x + halfSize, cube.y + halfSize, cube.z + halfSize],
    ]
    return (
        <>
            {corners.map((corner, index) => (
                <mesh key={index} position={corner}>

                    console.log(`boxGeometry cube`, cube, `size`, size)

                    <boxGeometry args={[size, size, size]} />
                    <meshBasicMaterial color="red" />
                </mesh>
            ))}
        </>
    )
}
